urlset:
  {%- comment -%}
    Determine the default lastmod based on the referencing page's modification time.
  {%- endcomment -%}
  {%- assign default_lastmod = page.last_modified_at | default: page.date | default: site.time -%}

  {%- comment -%}
    1. Parse custom URLs from the page content (plain text URLs written line by line).
  {%- endcomment -%}
  {%- capture newline %}
{% endcapture -%}
  {%- assign content_lines = page.content | split: newline -%}
  {%- for line in content_lines -%}
    {%- assign url_loc = line | strip -%}
    {%- if url_loc != "" -%}
      {%- comment -%} Verify if it's a URL (starts with http or /) {%- endcomment -%}
      {%- assign first_char = url_loc | slice: 0 -%}
      {%- assign first_four = url_loc | slice: 0, 4 -%}
      {%- if first_four == "http" or first_char == "/" -%}

          {{ url_loc | absolute_url }}
          {{ default_lastmod | date_to_xmlschema }}

      {%- endif -%}
    {%- endif -%}
  {%- endfor -%}

  {%- comment -%}
    2. Parse custom URLs from page Front Matter or site _config.yml (strictly named for sitemap).
  {%- endcomment -%}
  {%- assign custom_urls = page.sitemap_urls | default: site.sitemap_custom_urls | default: site.sitemap.custom_urls -%}
  {%- if custom_urls -%}
    {%- for item in custom_urls -%}
      {%- assign url_loc = nil -%}
      {%- assign lastmod = nil -%}
      {%- assign changefreq = nil -%}
      {%- assign priority = nil -%}

      {%- if item.url or item.loc -%}
        {%- assign url_loc = item.url | default: item.loc -%}
        {%- assign lastmod = item.lastmod | default: item.last_modified_at | default: item.date -%}
        {%- assign changefreq = item.changefreq -%}
        {%- assign priority = item.priority -%}
      {%- else -%}
        {%- assign url_loc = item -%}
      {%- endif -%}

      {%- if url_loc -%}
        {%- if lastmod == nil or lastmod == "" -%}
          {%- assign lastmod = default_lastmod -%}
        {%- endif -%}

          {{ url_loc | absolute_url }}
          {{ lastmod | date_to_xmlschema }}
          {%- if changefreq -%}
          {{ changefreq }}
          {%- endif -%}
          {%- if priority -%}
          {{ priority }}
          {%- endif -%}

      {%- endif -%}
    {%- endfor -%}
  {%- endif -%}

  {%- comment -%}
    3. Loop through all pages and posts in the Jekyll site.
  {%- endcomment -%}
  {%- assign collections = site.pages | concat: site.posts -%}
  {%- for item in collections -%}
    {%- assign include_item = true -%}

    {%- comment -%} Exclude items explicitly marked as sitemap: false or noindex: true {%- endcomment -%}
    {%- if item.sitemap == false or item.data.sitemap == false -%}
      {%- assign include_item = false -%}
    {%- elsif item.noindex == true or item.data.noindex == true -%}
      {%- assign include_item = false -%}
    {%- endif -%}

    {%- comment -%} Whitelist layouts: home, page, poetry, post. Exclude archive, redirect, sitemap, tags etc. {%- endcomment -%}
    {%- assign layout_name = item.layout | default: item.data.layout -%}
    {%- if layout_name != "home" and layout_name != "page" and layout_name != "poetry" and layout_name != "post" -%}
      {%- assign include_item = false -%}
    {%- endif -%}

    {%- comment -%} Exclude specific non-HTML/feed files or formats {%- endcomment -%}
    {%- assign ext = item.url | split: '.' | last -%}
    {%- if ext == "xml" or ext == "json" or ext == "txt" or ext == "css" or ext == "js" or ext == "webmanifest" -%}
      {%- assign include_item = false -%}
    {%- endif -%}

    {%- comment -%} Exclude 404 page {%- endcomment -%}
    {%- if item.url == "/404.html" or item.url == "/404" or item.url == "/404/" -%}
      {%- assign include_item = false -%}
    {%- endif -%}

    {%- if include_item and item.url -%}
      {%- assign lastmod = item.last_modified_at | default: item.data.last_modified_at | default: item.date | default: site.time -%}


        {{ item.url | absolute_url }}
        {{ lastmod | date_to_xmlschema }}
        {%- if item.sitemap.changefreq -%}
        {{ item.sitemap.changefreq }}
        {%- elsif item.changefreq -%}
        {{ item.changefreq }}
        {%- endif -%}
        {%- if item.sitemap.priority -%}
        {{ item.sitemap.priority }}
        {%- elsif item.priority -%}
        {{ item.priority }}
        {%- endif -%}

    {%- endif -%}
  {%- endfor -%}
